# -*- coding: utf-8 -*-
# Merzlyak 10, proof tasks 75–95. Sums by telescoping; 25.5(2), 25.6(2) checked numerically. Unchanged: 88, 90.
P = {'G10_TB_§25_25_11_2': {'k': 'Умножим сумму $S$ на $2\\sin 5^{\\circ}$: $2\\sin 5^{\\circ}\\sin 10k^{\\circ} = \\cos(10k - 5)^{\\circ} - \\cos(10k + 5)^{\\circ}$, и при $k = 1, \\ldots, 5$ слагаемые взаимно уничтожаются: $2\\sin 5^{\\circ} \\cdot S = \\cos 5^{\\circ} - \\cos 55^{\\circ} = 2\\sin 30^{\\circ}\\sin 25^{\\circ} = \\sin 25^{\\circ}$, откуда $S = \\dfrac{\\sin 25^{\\circ}}{2\\sin 5^{\\circ}}$.', 'd': [('После умножения на $2\\sin 5^{\\circ}$ получаем $\\cos 5^{\\circ} - \\cos 55^{\\circ} = 2\\sin 30^{\\circ}\\sin 25^{\\circ} = \\sin 25^{\\circ}$, откуда $S = \\dfrac{\\sin 25^{\\circ}}{\\sin 5^{\\circ}}$, поэтому равенство неверно.', 'Сумма умножалась на $2\\sin 5^{\\circ}$, поэтому делить нужно на $2\\sin 5^{\\circ}$.'), ('$\\sin 10^{\\circ} + \\sin 20^{\\circ} + \\ldots + \\sin 50^{\\circ} = \\sin 150^{\\circ} = \\dfrac{1}{2}$, а правая часть не равна $\\dfrac{1}{2}$, поэтому равенство неверно.', 'Сумма синусов не равна синусу суммы углов.'), ('$2\\sin 5^{\\circ}\\sin 10k^{\\circ} = \\cos(10k + 5)^{\\circ} - \\cos(10k - 5)^{\\circ}$, поэтому $2\\sin 5^{\\circ} \\cdot S = \\cos 55^{\\circ} - \\cos 5^{\\circ} = -\\sin 25^{\\circ}$, и $S < 0$, поэтому равенство неверно.', '$2\\sin x\\sin y = \\cos(x - y) - \\cos(x + y)$: разность записана в обратном порядке.')]}, 'G10_TB_§25_25_12': {'k': 'Умножим сумму $S$ на $2\\sin\\dfrac{\\pi}{19}$: $2\\sin\\dfrac{\\pi}{19}\\cos\\dfrac{(2k - 1)\\pi}{19} = \\sin\\dfrac{2k\\pi}{19} - \\sin\\dfrac{(2k - 2)\\pi}{19}$, и при $k = 1, \\ldots, 9$ сумма равна $\\sin\\dfrac{18\\pi}{19} = \\sin\\dfrac{\\pi}{19}$, поэтому $S = \\dfrac{1}{2}$.', 'd': [('После умножения на $2\\sin\\dfrac{\\pi}{19}$ сумма равна $\\sin\\dfrac{18\\pi}{19} = -\\sin\\dfrac{\\pi}{19}$, поэтому $S = -\\dfrac{1}{2}$, поэтому равенство неверно.', '$\\sin\\dfrac{18\\pi}{19} = \\sin\\left(\\pi - \\dfrac{\\pi}{19}\\right) = \\sin\\dfrac{\\pi}{19}$: во второй четверти синус положителен.'), ('Слагаемые попарно противоположны: $\\cos\\dfrac{17\\pi}{19} = -\\cos\\dfrac{\\pi}{19}$ и т. д., поэтому сумма равна $0$, поэтому равенство неверно.', '$\\cos\\dfrac{17\\pi}{19} = -\\cos\\dfrac{2\\pi}{19}$, а косинуса $\\dfrac{2\\pi}{19}$ в сумме нет: слагаемые не сокращаются.'), ('После умножения на $2\\sin\\dfrac{\\pi}{19}$ сумма равна $\\sin\\dfrac{18\\pi}{19} = \\sin\\dfrac{\\pi}{19}$, поэтому $S = 1$, поэтому равенство неверно.', 'Сумма умножалась на $2\\sin\\dfrac{\\pi}{19}$, поэтому $S = \\dfrac{\\sin\\frac{\\pi}{19}}{2\\sin\\frac{\\pi}{19}} = \\dfrac{1}{2}$.')]}, 'G10_TB_§25_25_5_1': {'k': '$\\sin\\alpha\\sin 3\\alpha = \\dfrac{\\cos 2\\alpha - \\cos 4\\alpha}{2}$, $\\sin 4\\alpha\\sin 8\\alpha = \\dfrac{\\cos 4\\alpha - \\cos 12\\alpha}{2}$, поэтому левая часть равна $\\dfrac{\\cos 2\\alpha - \\cos 12\\alpha}{2} = \\sin 7\\alpha\\sin 5\\alpha$.', 'd': [('$\\sin\\alpha\\sin 3\\alpha = \\dfrac{\\cos 2\\alpha + \\cos 4\\alpha}{2}$, $\\sin 4\\alpha\\sin 8\\alpha = \\dfrac{\\cos 4\\alpha + \\cos 12\\alpha}{2}$, и сумма не равна $\\sin 7\\alpha\\sin 5\\alpha$, поэтому тождество неверно.', '$\\sin x\\sin y = \\dfrac{\\cos(x - y) - \\cos(x + y)}{2}$: между косинусами стоит «−».'), ('Левая часть равна $\\dfrac{\\cos 2\\alpha - \\cos 12\\alpha}{2} = \\sin 7\\alpha\\cos 5\\alpha$, поэтому тождество неверно.', '$\\cos x - \\cos y = -2\\sin\\dfrac{x + y}{2}\\sin\\dfrac{x - y}{2}$, поэтому $\\dfrac{\\cos 2\\alpha - \\cos 12\\alpha}{2} = \\sin 7\\alpha\\sin 5\\alpha$.'), ('Левая часть равна $\\cos 2\\alpha - \\cos 12\\alpha = 2\\sin 7\\alpha\\sin 5\\alpha$, поэтому тождество неверно.', 'Каждое произведение даёт множитель $\\dfrac{1}{2}$: сумма равна $\\dfrac{\\cos 2\\alpha - \\cos 12\\alpha}{2}$.')]}, 'G10_TB_§25_25_5_2': {'k': 'По формулам произведения левая часть равна $\\dfrac{1}{2}\\left(\\sin\\left(\\dfrac{\\pi}{2} + 7\\alpha\\right) + \\sin 3\\alpha\\right) - \\dfrac{1}{2}\\left(\\cos 7\\alpha - \\cos\\left(\\dfrac{\\pi}{2} - 5\\alpha\\right)\\right) = \\dfrac{\\sin 3\\alpha + \\sin 5\\alpha}{2} = \\sin 4\\alpha\\cos\\alpha$.', 'd': [('Левая часть равна $\\dfrac{\\sin 3\\alpha - \\sin 5\\alpha}{2} = -\\cos 4\\alpha\\sin\\alpha$, поэтому тождество неверно.', '$\\cos\\left(\\dfrac{\\pi}{2} - 5\\alpha\\right) = \\sin 5\\alpha$ входит в разность со знаком «−» перед скобкой, т. е. с «+».'), ('$\\sin\\left(\\dfrac{\\pi}{4} + 5\\alpha\\right)\\cos\\left(\\dfrac{\\pi}{4} + 2\\alpha\\right) = \\sin 5\\alpha\\cos 2\\alpha$, так как слагаемые $\\dfrac{\\pi}{4}$ взаимно уничтожаются, поэтому левая часть равна $\\sin 5\\alpha\\cos 2\\alpha - \\sin\\alpha\\sin 6\\alpha$, поэтому тождество неверно.', 'Слагаемое $\\dfrac{\\pi}{4}$ внутри аргумента нельзя отбросить: $\\sin\\left(\\dfrac{\\pi}{4} + 5\\alpha\\right) \\ne \\sin 5\\alpha$.'), ('Левая часть равна $\\dfrac{\\sin 3\\alpha + \\sin 5\\alpha}{2} = \\sin 8\\alpha\\cos 2\\alpha$, поэтому тождество неверно.', '$\\sin x + \\sin y = 2\\sin\\dfrac{x + y}{2}\\cos\\dfrac{x - y}{2}$: берутся полусумма $4\\alpha$ и полуразность $\\alpha$.')]}, 'G10_TB_§25_25_6_1': {'k': '$\\cos 3\\alpha\\cos 6\\alpha = \\dfrac{\\cos 3\\alpha + \\cos 9\\alpha}{2}$, $\\cos 4\\alpha\\cos 7\\alpha = \\dfrac{\\cos 3\\alpha + \\cos 11\\alpha}{2}$, поэтому левая часть равна $\\dfrac{\\cos 9\\alpha - \\cos 11\\alpha}{2} = \\sin 10\\alpha\\sin\\alpha$.', 'd': [('Левая часть равна $\\dfrac{\\cos 9\\alpha - \\cos 11\\alpha}{2} = -\\sin 10\\alpha\\sin\\alpha$, поэтому тождество неверно.', '$\\cos x - \\cos y = -2\\sin\\dfrac{x + y}{2}\\sin\\dfrac{x - y}{2}$, и $\\sin(-\\alpha) = -\\sin\\alpha$: минусы сокращаются.'), ('$\\cos 3\\alpha\\cos 6\\alpha = \\dfrac{\\cos 3\\alpha - \\cos 9\\alpha}{2}$, $\\cos 4\\alpha\\cos 7\\alpha = \\dfrac{\\cos 3\\alpha - \\cos 11\\alpha}{2}$, поэтому левая часть равна $\\dfrac{\\cos 11\\alpha - \\cos 9\\alpha}{2}$, поэтому тождество неверно.', '$\\cos x\\cos y = \\dfrac{\\cos(x - y) + \\cos(x + y)}{2}$: между косинусами «+».'), ('$\\cos 3\\alpha\\cos 6\\alpha - \\cos 4\\alpha\\cos 7\\alpha = \\cos 18\\alpha - \\cos 28\\alpha$, и это не равно $\\sin 10\\alpha\\sin\\alpha$, поэтому тождество неверно.', 'Произведение косинусов не равно косинусу произведения углов.')]}, 'G10_TB_§25_25_6_2': {'k': '$2\\sin\\left(\\dfrac{\\alpha}{4} + 15^{\\circ}\\right)\\cos\\left(\\dfrac{\\alpha}{4} - 15^{\\circ}\\right) = \\sin\\dfrac{\\alpha}{2} + \\sin 30^{\\circ}$, поэтому левая часть равна $\\cos\\dfrac{\\alpha}{2}\\sin\\dfrac{\\alpha}{2} + \\dfrac{1}{2}\\cos\\dfrac{\\alpha}{2} = \\dfrac{1}{2}\\left(\\sin\\alpha + \\cos\\dfrac{\\alpha}{2}\\right)$; правая часть по формуле произведения равна $\\dfrac{1}{2}\\left(\\sin\\left(90^{\\circ} - \\dfrac{\\alpha}{2}\\right) + \\sin\\alpha\\right) = \\dfrac{1}{2}\\left(\\cos\\dfrac{\\alpha}{2} + \\sin\\alpha\\right)$.', 'd': [('$2\\sin\\left(\\dfrac{\\alpha}{4} + 15^{\\circ}\\right)\\cos\\left(\\dfrac{\\alpha}{4} - 15^{\\circ}\\right) = \\sin\\dfrac{\\alpha}{2} - \\sin 30^{\\circ}$, поэтому левая часть равна $\\dfrac{1}{2}\\left(\\sin\\alpha - \\cos\\dfrac{\\alpha}{2}\\right)$, поэтому тождество неверно.', '$2\\sin x\\cos y = \\sin(x + y) + \\sin(x - y)$, а $x - y = 30^{\\circ}$, поэтому $+\\sin 30^{\\circ}$.'), ('Левая часть равна $\\dfrac{1}{2}\\left(\\sin\\alpha + \\cos\\dfrac{\\alpha}{2}\\right)$, а правая $\\dfrac{1}{2}\\left(\\sin\\left(90^{\\circ} - \\dfrac{\\alpha}{2}\\right) - \\sin\\alpha\\right) = \\dfrac{1}{2}\\left(\\cos\\dfrac{\\alpha}{2} - \\sin\\alpha\\right)$, поэтому тождество неверно.', '$\\left(45^{\\circ} + \\dfrac{\\alpha}{4}\\right) - \\left(45^{\\circ} - \\dfrac{3\\alpha}{4}\\right) = \\alpha$, и $\\sin\\alpha$ входит со знаком «+».'), ('$2\\sin\\left(\\dfrac{\\alpha}{4} + 15^{\\circ}\\right)\\cos\\left(\\dfrac{\\alpha}{4} - 15^{\\circ}\\right) = \\sin\\dfrac{\\alpha}{2}$, поэтому левая часть равна $\\dfrac{1}{2}\\sin\\alpha$, а правая больше, поэтому тождество неверно.', 'Потеряно слагаемое $\\sin(x - y) = \\sin 30^{\\circ} = \\dfrac{1}{2}$.')]}, 'G10_TB_§25_25_9_1': {'k': '$\\sin 60^{\\circ} = \\dfrac{\\sqrt{3}}{2}$, а $\\sin 20^{\\circ}\\sin 40^{\\circ}\\sin 80^{\\circ} = \\sin 20^{\\circ}\\sin(60^{\\circ} - 20^{\\circ})\\sin(60^{\\circ} + 20^{\\circ}) = \\dfrac{\\sin 60^{\\circ}}{4} = \\dfrac{\\sqrt{3}}{8}$ по формуле $\\sin x\\sin(60^{\\circ} - x)\\sin(60^{\\circ} + x) = \\dfrac{\\sin 3x}{4}$, поэтому левая часть равна $16 \\cdot \\dfrac{\\sqrt{3}}{2} \\cdot \\dfrac{\\sqrt{3}}{8} = 3$.', 'd': [('$\\sin 20^{\\circ}\\sin 40^{\\circ}\\sin 80^{\\circ} = \\sin 60^{\\circ} = \\dfrac{\\sqrt{3}}{2}$, поэтому левая часть равна $16 \\cdot \\dfrac{3}{4} = 12$, поэтому равенство неверно.', '$\\sin x\\sin(60^{\\circ} - x)\\sin(60^{\\circ} + x) = \\dfrac{\\sin 3x}{4}$: множитель $\\dfrac{1}{4}$ потерян.'), ('$\\sin 20^{\\circ}\\sin 40^{\\circ}\\sin 80^{\\circ} = \\dfrac{\\sin 60^{\\circ}}{4} = \\dfrac{\\sqrt{3}}{8}$, поэтому левая часть равна $16 \\cdot \\dfrac{\\sqrt{3}}{8} = 2\\sqrt{3}$, поэтому равенство неверно.', 'Потерян множитель $\\sin 60^{\\circ} = \\dfrac{\\sqrt{3}}{2}$ из условия.'), ('$\\sin 20^{\\circ}\\sin 40^{\\circ}\\sin 60^{\\circ}\\sin 80^{\\circ} = \\sin(20^{\\circ} + 40^{\\circ} + 60^{\\circ} + 80^{\\circ}) = \\sin 200^{\\circ} < 0$, поэтому равенство неверно.', 'Произведение синусов не равно синусу суммы углов.')]}, 'G10_TB_§25_25_9_2': {'k': '$\\sin 50^{\\circ} = \\sin(60^{\\circ} - 10^{\\circ})$, $\\sin 70^{\\circ} = \\sin(60^{\\circ} + 10^{\\circ})$, и по формуле $\\sin x\\sin(60^{\\circ} - x)\\sin(60^{\\circ} + x) = \\dfrac{\\sin 3x}{4}$ левая часть равна $8 \\cdot \\dfrac{\\sin 30^{\\circ}}{4} = 1$.', 'd': [('По формуле $\\sin x\\sin(60^{\\circ} - x)\\sin(60^{\\circ} + x) = \\dfrac{\\sin 3x}{4}$ левая часть равна $8 \\cdot \\dfrac{\\sin 30^{\\circ}}{4} = 2$, поэтому равенство неверно.', '$\\sin 30^{\\circ} = \\dfrac{1}{2}$, поэтому $8 \\cdot \\dfrac{1}{8} = 1$.'), ('$\\sin 10^{\\circ}\\sin 50^{\\circ}\\sin 70^{\\circ} = \\sin 3x$ при $x = 10^{\\circ}$, поэтому левая часть равна $8\\sin 30^{\\circ} = 4$, поэтому равенство неверно.', '$\\sin x\\sin(60^{\\circ} - x)\\sin(60^{\\circ} + x) = \\dfrac{\\sin 3x}{4}$: множитель $\\dfrac{1}{4}$ потерян.'), ('$\\sin 50^{\\circ} = \\cos 50^{\\circ}$ и $\\sin 70^{\\circ} = \\cos 70^{\\circ}$, поэтому произведение равно $8\\sin 10^{\\circ}\\cos 50^{\\circ}\\cos 70^{\\circ}$, и оно не равно $1$, поэтому равенство неверно.', '$\\sin 50^{\\circ} = \\cos 40^{\\circ}$ и $\\sin 70^{\\circ} = \\cos 20^{\\circ}$: берётся дополнительный угол.')]}, 'G10_TB_§37_37_12_1': {'k': "Угловой коэффициент касательной $f'(x_{0}) = -1 - 3x_{0}^{2} \\le -1 < 0$ при любом $x_{0}$, т. е. тангенс угла наклона отрицателен, и угол тупой.", 'd': [("$f'(x) = 6 - 1 - 3x^{2}$, и при $x^{2} < \\dfrac{5}{3}$ производная положительна, поэтому угол не всегда тупой.", "Производная постоянной $6$ равна нулю: $f'(x) = -1 - 3x^{2}$."), ("$f'(x) = -1 - 3x^{2}$, и при $x = 0$ она равна нулю, поэтому касательная в этой точке горизонтальна.", "$f'(0) = -1 \\ne 0$."), ("$f'(x) = -1 + 3x^{2}$, и при $|x| > \\dfrac{1}{\\sqrt{3}}$ она положительна, поэтому угол может быть острым.", "$(-x^{3})' = -3x^{2}$: знак потерян.")]}, 'G10_TB_§37_37_12_2': {'k': "$f'(x) = \\dfrac{-(x - 3) - (5 - x)}{(x - 3)^{2}} = -\\dfrac{2}{(x - 3)^{2}} < 0$ при всех $x \\ne 3$, т. е. угловой коэффициент любой касательной отрицателен, и угол тупой.", 'd': [("$f'(x) = \\dfrac{-(x - 3) + (5 - x)}{(x - 3)^{2}} = \\dfrac{8 - 2x}{(x - 3)^{2}}$, и при $x < 4$ она положительна, поэтому угол может быть острым.", "В формуле производной частного $\\dfrac{u'v - uv'}{v^{2}}$ перед $uv'$ стоит «−»."), ("$f'(x) = \\dfrac{(5 - x)'}{(x - 3)'} = -1 < 0$, поэтому угол тупой и равен $135^{\\circ}$.", 'Производная частного не равна частному производных.'), ("$f'(x) = \\dfrac{2}{(x - 3)^{2}} > 0$, поэтому угол острый.", "$-(x - 3) - (5 - x) = -2$, поэтому $f'(x) = -\\dfrac{2}{(x - 3)^{2}}$.")]}, 'G10_TB_§37_37_13_1': {'k': "Угловой коэффициент касательной $f'(x_{0}) = 5x_{0}^{4} + 2 \\ge 2 > 0$ при любом $x_{0}$, т. е. тангенс угла наклона положителен, и угол острый.", 'd': [('Угол острый только при $x_{0} > 0$: при отрицательных $x_{0}$ производная может стать отрицательной из-за нечётной степени.', "$f'(x) = 5x^{4} + 2$: чётная степень $x^{4}$ неотрицательна при любом $x$."), ("$f'(x) = 5x^{4} + 2$ обращается в нуль при $x = -\\sqrt[4]{0{,}4}$, поэтому в этой точке касательная горизонтальна.", '$5x^{4} + 2 \\ge 2 > 0$: уравнение $5x^{4} = -2$ не имеет решений.'), ('Функция $f(x) = x^{5} + 2x - 8$ принимает отрицательные значения при $x < 1$, поэтому там касательная наклонена под тупым углом.', 'Угол наклона определяется знаком производной, а не знаком значения функции.')]}, 'G10_TB_§37_37_13_2': {'k': "$f'(x) = \\left(4(1 - x)^{-1}\\right)' = 4(1 - x)^{-2} = \\dfrac{4}{(1 - x)^{2}} > 0$ при всех $x \\ne 1$, т. е. угловой коэффициент любой касательной положителен, и угол острый.", 'd': [("$f'(x) = -\\dfrac{4}{(1 - x)^{2}} < 0$, поэтому угол тупой.", "Производная внутренней функции $(1 - x)' = -1$ даёт ещё один множитель $-1$: $f'(x) = \\dfrac{4}{(1 - x)^{2}}$."), ("$f'(x) = \\dfrac{4}{1 - x}$, и при $x > 1$ она отрицательна, поэтому угол острый только при $x < 1$.", "$f'(x) = \\dfrac{4}{(1 - x)^{2}}$: знаменатель в квадрате, и производная положительна при всех $x \\ne 1$."), ('При $x \\to 1$ знаменатель обращается в нуль, поэтому касательная вертикальна, и угол прямой.', "Точка $x = 1$ не входит в область определения, и касательной в ней нет; в остальных точках $f'(x) > 0$.")]}, 'G10_TB_§38_38_10_1': {'k': "$f'(x) = -1 + x - x^{2} = -\\left(\\left(x - \\dfrac{1}{2}\\right)^{2} + \\dfrac{3}{4}\\right) < 0$ при всех $x \\in \\mathbb{R}$, поэтому функция убывает.", 'd': 'KEEP'}, 'G10_TB_§3_3_3_2': {'d': [('Функция не является обратимой, так как она не сюръективна: область значений $(0; +\\infty)$, а не все действительные числа.', 'Обратимость означает, что разным $x$ соответствуют разные $y$; множество значений здесь ни при чём.'), ('Функция не является обратимой, потому что она не определена в точке $x = 0$.', 'Функция может быть обратимой и не на всей прямой (например, $y = \\dfrac{1}{x}$); важно, что $y(1) = y(-1)$.'), ('Функция не является обратимой, потому что она убывает при $x > 0$.', 'Строго монотонная функция как раз обратима; причина — возрастание при $x < 0$ и убывание при $x > 0$ с совпадающими значениями, например $y(1) = y(-1) = 1$.')]}, 'G10_TB_§42_42_43_1': {'k': '$\\sin\\alpha\\sin\\beta(\\operatorname{ctg}\\alpha + \\operatorname{ctg}\\beta) = \\sin\\alpha\\sin\\beta \\cdot \\dfrac{\\cos\\alpha\\sin\\beta + \\sin\\alpha\\cos\\beta}{\\sin\\alpha\\sin\\beta} = \\sin(\\alpha + \\beta)$.', 'd': [('$\\sin\\alpha\\sin\\beta(\\operatorname{ctg}\\alpha + \\operatorname{ctg}\\beta) = \\cos\\alpha\\sin\\beta + \\cos\\beta\\sin\\alpha = \\cos(\\alpha + \\beta)$, поэтому тождество неверно.', '$\\sin\\alpha\\cos\\beta + \\cos\\alpha\\sin\\beta = \\sin(\\alpha + \\beta)$; это формула синуса суммы.'), ('$\\sin\\alpha\\sin\\beta(\\operatorname{ctg}\\alpha + \\operatorname{ctg}\\beta) = \\sin\\alpha\\operatorname{ctg}\\alpha + \\sin\\beta\\operatorname{ctg}\\beta = \\cos\\alpha + \\cos\\beta$, поэтому тождество неверно.', 'Каждый котангенс умножается на оба синуса: $\\sin\\alpha\\sin\\beta\\operatorname{ctg}\\alpha = \\cos\\alpha\\sin\\beta$.'), ('$\\sin\\alpha\\sin\\beta(\\operatorname{ctg}\\alpha + \\operatorname{ctg}\\beta) = \\sin\\alpha\\sin\\beta \\cdot \\dfrac{\\cos\\alpha + \\cos\\beta}{\\sin\\alpha + \\sin\\beta}$, и это не равно $\\sin(\\alpha + \\beta)$, поэтому тождество неверно.', 'Дроби складывают через общий знаменатель $\\sin\\alpha\\sin\\beta$, а не складывая числители и знаменатели.')]}, 'G10_TB_§42_42_43_2': {'k': 'Числитель $2\\sin\\alpha\\cos\\beta - (\\sin\\alpha\\cos\\beta - \\cos\\alpha\\sin\\beta) = \\sin(\\alpha + \\beta)$, знаменатель $(\\cos\\alpha\\cos\\beta + \\sin\\alpha\\sin\\beta) - 2\\sin\\alpha\\sin\\beta = \\cos(\\alpha + \\beta)$, поэтому дробь равна $\\operatorname{tg}(\\alpha + \\beta)$.', 'd': [('Числитель равен $\\sin(\\alpha - \\beta)$, знаменатель $\\cos(\\alpha - \\beta)$, поэтому дробь равна $\\operatorname{tg}(\\alpha - \\beta)$, поэтому тождество неверно.', '$2\\sin\\alpha\\cos\\beta - \\sin\\alpha\\cos\\beta + \\cos\\alpha\\sin\\beta = \\sin\\alpha\\cos\\beta + \\cos\\alpha\\sin\\beta = \\sin(\\alpha + \\beta)$.'), ('$\\sin(\\alpha - \\beta) = \\sin\\alpha\\cos\\beta + \\cos\\alpha\\sin\\beta$, поэтому числитель равен $\\sin\\alpha\\cos\\beta - \\cos\\alpha\\sin\\beta$, и дробь равна $\\dfrac{\\sin(\\alpha - \\beta)}{\\cos(\\alpha + \\beta)}$, поэтому тождество неверно.', '$\\sin(\\alpha - \\beta) = \\sin\\alpha\\cos\\beta - \\cos\\alpha\\sin\\beta$: знак перед вторым произведением «−».'), ('Числитель равен $\\sin(\\alpha + \\beta)$, знаменатель $\\cos(\\alpha - \\beta) - 2\\sin\\alpha\\sin\\beta = \\sin(\\alpha + \\beta)$, поэтому дробь равна $1$, поэтому тождество неверно.', '$\\cos\\alpha\\cos\\beta - \\sin\\alpha\\sin\\beta = \\cos(\\alpha + \\beta)$, а не $\\sin(\\alpha + \\beta)$.')]}, 'G10_TB_§42_42_43_3': {'k': 'Числитель $\\sqrt{2}\\cos\\alpha - 2\\left(\\dfrac{\\sqrt{2}}{2}\\cos\\alpha - \\dfrac{\\sqrt{2}}{2}\\sin\\alpha\\right) = \\sqrt{2}\\sin\\alpha$, знаменатель $2\\left(\\dfrac{\\sqrt{2}}{2}\\cos\\alpha + \\dfrac{\\sqrt{2}}{2}\\sin\\alpha\\right) - \\sqrt{2}\\sin\\alpha = \\sqrt{2}\\cos\\alpha$, поэтому дробь равна $\\operatorname{tg}\\alpha$.', 'd': [('Числитель $\\sqrt{2}\\cos\\alpha - 2\\left(\\dfrac{\\sqrt{2}}{2}\\cos\\alpha + \\dfrac{\\sqrt{2}}{2}\\sin\\alpha\\right) = -\\sqrt{2}\\sin\\alpha$, знаменатель $\\sqrt{2}\\cos\\alpha$, поэтому дробь равна $-\\operatorname{tg}\\alpha$, поэтому тождество неверно.', '$\\cos\\left(\\dfrac{\\pi}{4} + \\alpha\\right) = \\cos\\dfrac{\\pi}{4}\\cos\\alpha - \\sin\\dfrac{\\pi}{4}\\sin\\alpha$: знак «−».'), ('Числитель равен $\\sqrt{2}\\sin\\alpha$, знаменатель $\\sqrt{2}\\cos\\alpha$, поэтому дробь равна $\\operatorname{ctg}\\alpha$, поэтому тождество неверно.', '$\\dfrac{\\sin\\alpha}{\\cos\\alpha} = \\operatorname{tg}\\alpha$.'), ('$\\cos\\left(\\dfrac{\\pi}{4} + \\alpha\\right) = \\cos\\dfrac{\\pi}{4} + \\cos\\alpha$ и $\\sin\\left(\\dfrac{\\pi}{4} + \\alpha\\right) = \\sin\\dfrac{\\pi}{4} + \\sin\\alpha$, поэтому дробь равна $\\dfrac{-\\sqrt{2} - \\cos\\alpha}{\\sqrt{2} + \\sin\\alpha}$, поэтому тождество неверно.', 'Косинус и синус суммы не равны сумме косинусов и синусов.')]}, 'G10_TB_§4_3_12': {'k': "Из $y = kx + b$ при $k \\ne 0$ получаем $x = \\dfrac{1}{k}y - \\dfrac{b}{k}$, т. е. обратная функция $y = \\dfrac{1}{k}x - \\dfrac{b}{k}$ имеет вид $y = k'x + b'$ с $k' = \\dfrac{1}{k}$, $b' = -\\dfrac{b}{k}$, т. е. линейна.", 'd': [('Из $y = kx + b$ получаем $x = \\dfrac{y}{k} + \\dfrac{b}{k}$, т. е. обратная функция $y = \\dfrac{1}{k}x + \\dfrac{b}{k}$ — линейная.', '$kx = y - b$, поэтому $x = \\dfrac{y - b}{k} = \\dfrac{1}{k}y - \\dfrac{b}{k}$: знак свободного члена потерян.'), ('Из $y = kx + b$ получаем $x = ky - b$, т. е. обратная функция $y = kx - b$ — линейная.', 'Чтобы выразить $x$, нужно разделить на $k$, а не умножить.'), ('Обратная функция получается симметрией графика относительно оси $Oy$, а прямая при такой симметрии остаётся прямой: $y = -kx + b$.', 'График обратной функции симметричен исходному относительно прямой $y = x$, а не оси $Oy$.')]}, 'G10_TB_§4_3_13': {'k': 'Множество значений нечётной функции $f$ симметрично относительно нуля, и если $y = f(x)$, то $-y = f(-x)$; поэтому $f^{-1}(-y) = -x = -f^{-1}(y)$, т. е. $f^{-1}$ нечётна.', 'd': [('Если $y = f(x)$, то $-y = f(-x)$, поэтому $f^{-1}(-y) = x = f^{-1}(y)$, т. е. $f^{-1}$ чётна.', 'Из $-y = f(-x)$ следует $f^{-1}(-y) = -x$, а не $x$.'), ('Если $y = f(x)$, то $-y = -f(x) = f(x)$, поэтому $f^{-1}(-y) = f^{-1}(y)$.', '$-f(x) = f(-x)$, а не $f(x)$: это равенство верно лишь для чётной функции.'), ('Функция $f^{-1}$ нечётна, так как $f^{-1}(0) = 0$.', 'Равенство $f^{-1}(0) = 0$ не доказывает нечётности; нужно $f^{-1}(-y) = -f^{-1}(y)$ при всех $y$.')]}}
